        W3CDom dom = new W3CDom();
        boolean actual = dom.namespaceAware();
        assertNotNull(actual);
    }

    @Test
    public void namespaceAwareBooleanTest() {
        W3CDom dom = new W3CDom();
        dom = dom.namespaceAware(false);
        assertNotNull(dom);
        assertFalse(dom.namespaceAware());
    }

